export const COMMUNICATIONS_CONTEXTS={};
for(const [key,ids]of Object.entries(COMMUNICATIONS_SCENE_PARTS)){
  const [view,variant]=key.split('/');
  for(const id of ids){const contexts=COMMUNICATIONS_CONTEXTS[id]||={};(contexts[view]||=[]).push(variant);}
}
export function applyCommsCatalog(SOURCES,CONCEPTS){
  for(const item of COMMUNICATIONS_SOURCES){const old=SOURCES.find(s=>s.id===item.id);if(old)Object.assign(old,item);else SOURCES.push(item);}
  for(const item of COMMUNICATIONS_CONCEPTS){const old=CONCEPTS.find(c=>c.id===item.id);if(old)Object.assign(old,item);else CONCEPTS.push(item);}
  for(const item of COMMUNICATIONS_CONCEPT_UPDATES){const old=CONCEPTS.find(c=>c.id===item.id);if(old)Object.assign(old,item);}
}
export function applyCommsConfig({SYSTEMS,NEW_VIEWS,PART_VIEWS,PART_VARIANTS,PART_CONTEXTS,PART_VIEW_VARIANTS,PART_RELATIONS}){
  Object.assign(NEW_VIEWS,COMMUNICATIONS_VIEW_DATA);
  const comms=SYSTEMS.find(s=>s.id==='communications');
  if(comms){const oldViews=comms.views||[];Object.assign(comms,{label:'Communications',short:'Communications',description:'Locations, networks, SCADA, operational voice, passenger information and security interfaces.',view:'communications-overview',component:'communications-system',views:[...Object.keys(COMMUNICATIONS_VIEW_DATA),...oldViews.filter(v=>!Object.hasOwn(COMMUNICATIONS_VIEW_DATA,v))],parts:[...new Set([...(comms.parts||[]),...Object.keys(COMMUNICATIONS_PRIMARY)])],groups:[
    {id:'communications-map',label:'Locations & transport',views:['communications-overview','communications-network'],parts:['communications-system','fiber-backbone','fiber-patch-panel','optical-transceiver','network-switch','communications-router','onboard-ethernet-gateway','communications-power']},
    {id:'communications-supervision',label:'Supervisory interfaces',views:['communications-scada'],parts:['station-scada','scada-rtu','scada-input-module','scada-output-module','scada-gateway','scada-head-end','scada-information-quality']},
    {id:'communications-services',label:'Voice & passenger services',views:['communications-telephony','communications-passenger','communications-security'],parts:['emergency-intercom','help-point-electronics','voice-call-server','operational-cab-radio','pis-controller','pa-controller','pa-amplifier','station-pa','station-pis','camera-imager','cctv-recording','access-door-interface']},
  ]});}
  for(const [id,[view,variant]]of Object.entries(COMMUNICATIONS_PRIMARY)){PART_VIEWS[id]=view;PART_VARIANTS[id]=variant;}
  // These existing onboard concepts previously inherited the domain's original
  // overview. Retain their real primary anchors when the domain gains a new map.
  for(const id of ['train-radio','radio-antenna','passenger-info','pa-intercom','cctv','train-network']){
    PART_VIEWS[id]='communications';PART_VARIANTS[id]='default';
  }
  for(const [id,contexts]of Object.entries(COMMUNICATIONS_CONTEXTS)){
    // Earlier catalog modules may retain these objects as their own published
    // context contracts. Extend navigation without mutating another module.
    PART_CONTEXTS[id]=[...(PART_CONTEXTS[id]||[])];PART_VIEW_VARIANTS[id]={...(PART_VIEW_VARIANTS[id]||{})};
    for(const [view,variants]of Object.entries(contexts)){if(!PART_CONTEXTS[id].includes(view))PART_CONTEXTS[id].push(view);PART_VIEW_VARIANTS[id][view]=variants;}
  }
  for(const item of [...COMMUNICATIONS_CONCEPTS,...COMMUNICATIONS_CONCEPT_UPDATES])if(item.related)PART_RELATIONS[item.id]=item.related;
}

export const COMMUNICATIONS_READING_GUIDES=[{
  id:'communications-guide',domain:'communications',component:'communications-system',title:'Read a communications system from endpoint to endpoint',summary:'Begin with a person or a physical condition, locate the equipment, and distinguish the information from the action it may support.',
  sections:[
    {heading:'Start with a service and its locations',text:'A communications drawing becomes easier to read when the endpoints are named before the network is drawn. A passenger speaking at a help point, a position contact in a plant room, a crew member using a cab radio and a camera producing video are different sources. Their recipients also differ: an assigned answering role, a supervisory application, an operational fixed terminal or a video recorder. The Locations & connections view therefore changes the service as well as its equipment. Its train, wayside, station and head-end places are teaching categories. They are not four mandatory rooms, a real route layout or a claim that all services use the same transport network.',sources:['F20','CM01','CM06','CM12']},
    {heading:'Separate passive connections, active equipment and supply',text:'The station rack brings several boundaries close enough to inspect. Installed fibre terminates at a passive panel. A patch lead reaches an optical module at a powered switch. A routing interface connects network scopes, while a supply or UPS supports electrical continuity. Opening and separating these assemblies answers a different question from tracing information in Connections: what physical object could be inspected or replaced? The onboard alternative then changes the physical setting. It distinguishes local device connections from an inter-consist backbone. Its rugged modules and vehicle sections are original geometry, without a vendor port layout, network address plan or assumed train-control safety function.',sources:['CM03','CM04','F20','F19']},
    {heading:'Read SCADA in both directions',text:'A field condition does not appear on an HMI without acquisition and communications. The status example shows a damper position, its contact, an input module, a local controller and the downstream presentation. The command example adds a separately visible output interface. It keeps the operator request, relay state, physical movement and returned indication distinct. Their invented delays make the relationships inspectable, but do not implement local permissives or protection. Stale indication is a selected comparison: the physical equipment and a last-known display disagree while quality is visibly impaired. The field state must not be inferred from the mere survival of a screen or network cabinet.',sources:['CM01','CM02','F17','OC02']},
    {heading:'Keep voice and passenger outputs purposeful',text:'A help point has transducers and call electronics, while its answering service has call state and an assigned recipient. The model presses a real button before showing a pending and then answered example. It does not promise a response time. Operational radio has a different access path, including cab equipment, an antenna and radio infrastructure. Its voice relationship is separate from train-control messages. Passenger information similarly distinguishes the source, local player and screen. PA adds a further physical boundary: an amplifier converts an audio service into power for a loudspeaker circuit. The moving cone explains a driver relationship; it says nothing about speech intelligibility or emergency priorities.',sources:['CM05','CM06','CM07','CM08','CM12']},
    {heading:'Distinguish observation from control and proof',text:'Camera optics, a video stream, recording storage and a viewing client are different pieces of a video system. An available live image does not establish that a recording exists, and neither proves track clearance or electrical isolation. Access control makes another useful distinction. The relay and bolt can change while the door remains closed. The contact changes when the leaf actually moves, and that measurement can then reach a security application. The demonstration deliberately separates these states. It provides no credential scheme, escape design or authorization to enter a railway work area. In each view, ask which object supplies the information, what its recipient can infer, and what independent evidence is still needed.',sources:['CM09','CM10','CM11']},
  ],sources:['F20','CM01','CM02','CM03','CM04','F19','F17','OC02','CM05','CM06','CM07','CM08','CM09','CM10','CM11','CM12'],
}];
